package dev.emanoel.shopcore.exception;
import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice
public class ApiExceptionHandler { record Problem(Instant timestamp,int status,String error,String message,Map<String,String> fields){} @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<Problem> notFound(ResourceNotFoundException e){return ResponseEntity.status(404).body(new Problem(Instant.now(),404,"Not Found",e.getMessage(),Map.of()));} @ExceptionHandler(BusinessException.class) ResponseEntity<Problem> business(BusinessException e){return ResponseEntity.badRequest().body(new Problem(Instant.now(),400,"Bad Request",e.getMessage(),Map.of()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Problem> validation(MethodArgumentNotValidException e){Map<String,String> f=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->f.putIfAbsent(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(new Problem(Instant.now(),400,"Validation Error","Invalid request",f));} }
